// cl: /DNDEBUG /MD /EHsc /O2 /Ob2
//
// Open-BFME5: the vector deleting destructor at retail 0x008A2ED0, 88 bytes.
// The body is compiler-generated by a delete[]; both deallocation functions
// are class-scoped and imported, and the scalar one takes the size.

class BfmeElemBV
{
	unsigned char m_bfmeDataBV[0x20];

public:
	~BfmeElemBV(void);

	__declspec(dllimport) static void operator delete(void *block, unsigned int size);

	__declspec(dllimport) static void operator delete[](void *block);
};

void bfmeDeleteArrayBV(BfmeElemBV *items)
{
	delete[] items;
}
